USE hospital_system;
CREATE OR REPLACE VIEW v_appointment_details AS SELECT a.appointment_id,a.patient_id,a.doctor_id,p.full_name AS patient_name,d.full_name AS doctor_name,dp.department_name,a.appointment_date,a.appointment_time,a.reason,a.status,a.created_at FROM appointment a JOIN patient p ON p.patient_id=a.patient_id JOIN doctor d ON d.doctor_id=a.doctor_id JOIN department dp ON dp.department_id=d.department_id;
CREATE OR REPLACE VIEW v_bill_summary AS SELECT b.bill_id,b.patient_id,b.appointment_id,p.full_name AS patient_name,b.bill_date,b.subtotal,b.tax,b.total_amount,COALESCE(SUM(py.amount),0) AS paid_amount,b.total_amount-COALESCE(SUM(py.amount),0) AS balance,CASE WHEN COALESCE(SUM(py.amount),0)>=b.total_amount THEN 'PAID' WHEN COALESCE(SUM(py.amount),0)>0 THEN 'PARTIALLY_PAID' ELSE 'UNPAID' END AS status FROM bill b JOIN patient p ON p.patient_id=b.patient_id LEFT JOIN payment py ON py.bill_id=b.bill_id GROUP BY b.bill_id,b.patient_id,b.appointment_id,p.full_name,b.bill_date,b.subtotal,b.tax,b.total_amount;
